-- St. Lucie Tax System — Consolidated Seed Data
-- Config, offices, hours, lunch shifts, transaction types, document registry,
-- prescreen questions, clerks, clerk schedules, and a sparse set of sample
-- appointments (~10% of capacity) for local dev / demo purposes.

BEGIN;

-- =============================================================================
-- Config (single row)
-- =============================================================================
-- schema.sql always runs before this file and inserts the singleton config row
-- (so a schema-only apply is already bookable). UPDATE that row rather than a
-- plain INSERT, which would violate the singleton unique index.
UPDATE config SET
    timezone = 'America/New_York',
    scheduling_block_padding = 0,
    default_lookahead_days = 14;

-- =============================================================================
-- Offices (2 locations, 3 desks each)
-- =============================================================================
INSERT INTO offices (name, address, total_desks, run_rate_pct) VALUES
    ('Fort Pierce Office',    '2300 Virginia Ave, Fort Pierce, FL 34982',          3, 100),
    ('St. Lucie West Office', '250 NW Country Club Dr, Port St. Lucie, FL 34986', 3, 100);

-- =============================================================================
-- Office Hours (Mon-Fri 8am-5pm)
-- =============================================================================
INSERT INTO office_hours (office_id, day_of_week, open_time, close_time) VALUES
    (1, 1, '08:00', '17:00'),
    (1, 2, '08:00', '17:00'),
    (1, 3, '08:00', '17:00'),
    (1, 4, '08:00', '17:00'),
    (1, 5, '08:00', '17:00'),
    (2, 1, '08:00', '17:00'),
    (2, 2, '08:00', '17:00'),
    (2, 3, '08:00', '17:00'),
    (2, 4, '08:00', '17:00'),
    (2, 5, '08:00', '17:00');

-- =============================================================================
-- Lunch Shifts (2 shifts per office, 45 min each)
-- Fort Pierce: 1 clerk out 11:30-12:15, then 2 clerks out 12:15-13:00
-- St. Lucie West: 2 clerks out 11:30-12:15, then 1 clerk out 12:15-13:00
-- =============================================================================
INSERT INTO office_lunch_shifts (office_id, shift_num, start_time, end_time) VALUES
    (1, 1, '11:30', '12:15'),
    (1, 2, '12:15', '13:00'),
    (2, 1, '11:30', '12:15'),
    (2, 2, '12:15', '13:00');

-- =============================================================================
-- Transaction Types (32 types, source: chatbot-prototype branch)
-- Insertion order determines serial id 1-32, referenced below by clerk skill_ids
-- =============================================================================
INSERT INTO transaction_types (txn_type_id, name, description, avg_duration_min, status, is_online_eligible, online_redirect_url, available_from, available_until) VALUES
('dl-transfer', 'Driver License Transfer (Out-of-State)', '{"summary": "Transfer an out-of-state or out-of-country driver license to Florida. Required for new Florida residents within 30 days of establishing residency.", "keywords": ["license", "DL", "driver", "transfer", "out of state", "new resident", "moved", "relocate", "Florida license", "exchange"], "commonPhrases": ["I just moved from another state", "I need a Florida license", "transfer my license", "new to Florida", "I moved here from", "exchange my out-of-state license", "I''m a new resident"], "requiredDocumentSummary": "One primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad), your Social Security card (copies not accepted), and two proofs of St. Lucie County residential address (utility bill, bank statement, lease agreement, deed, voter registration card, etc.). Your current out-of-state license is also required. If your name has changed, bring certified name change documents.", "requiredDocuments": ["Primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card (copies not accepted)", "Two proofs of St. Lucie County residential address (deed, mortgage statement, lease, utility bill, voter registration card, bank statement, etc.)", "Current out-of-state driver license", "Certified name change documents if name has changed since primary ID was issued (marriage certificate, divorce decree, or court order -- church-issued marriage certificates not accepted)"], "onlineEligible": false, "relatedTransactionIds": ["vehicle-title-transfer", "vehicle-registration"], "relatedPrompts": {"vehicle-title-transfer": "Since you''re moving to Florida, do you also need to transfer a vehicle title from another state?", "vehicle-registration": "Would you also like to register your vehicle in Florida?"}, "notes": "New residents must obtain a Florida license within 30 days. REAL ID upgrade is available during this process. If the customer has an out-of-state vehicle, they likely also need title transfer and registration. Beginning Feb. 6, 2026, all DL exams are administered exclusively in English. Church-issued marriage certificates are not accepted for name changes. Only St. Lucie County residents are served."}', 25, 'active', FALSE, NULL, NULL, NULL),
('dl-renewal', 'Driver License Renewal', '{"summary": "Renew an existing Florida driver license or ID card. Available for Florida residents with a current or recently expired FL DL/ID.", "keywords": ["renew", "renewal", "license", "DL", "driver", "expired", "expiring", "ID card"], "commonPhrases": ["renew my license", "my license is expiring", "my license expired", "I need to renew my DL", "renew my Florida ID", "license renewal"], "requiredDocumentSummary": "Current or expired Florida driver license. If your license is not REAL ID compliant and you want to upgrade: one primary identity document, your Social Security card (copies not accepted), and two proofs of St. Lucie County residential address.", "requiredDocuments": ["Current or expired Florida driver license", "Primary identity document (if not already REAL ID compliant -- US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card (if not already REAL ID compliant -- copies not accepted)", "Two proofs of St. Lucie County residential address (if not already REAL ID compliant)"], "onlineEligible": true, "onlineUrl": "https://mydmvportal.flhsmv.gov/Home/en/Account/Landing", "relatedTransactionIds": ["dl-address-change", "dl-name-change"], "relatedPrompts": {"dl-address-change": "Has your address changed since your last renewal? If so, we can update that at the same time.", "dl-name-change": "Has your legal name changed? If so, we can update that during your renewal."}, "notes": "Many renewals can be completed online at mydmvportal.flhsmv.gov or by mail. In-person required if: upgrading to REAL ID, vision test needed (mandatory for age 80+), or license expired more than 12 months. Customers 79 and under receive an 8-year license; customers 80+ receive a 6-year license."}', 15, 'active', TRUE, 'https://mydmvportal.flhsmv.gov/Home/en/Account/Landing', NULL, NULL),
('dl-name-change', 'Driver License Name Change', '{"summary": "Update your legal name on your Florida driver license or ID card due to marriage, divorce, or court order.", "keywords": ["name change", "married", "marriage", "divorce", "legal name", "maiden name", "new name", "update name"], "commonPhrases": ["I got married and need to change my name", "change the name on my license", "update my name on my DL", "I had a legal name change", "my name changed after divorce"], "requiredDocumentSummary": "Current Florida driver license, certified name change documentation (marriage certificate, divorce decree, certificate of naturalization showing new name, or court order -- church-issued certificates not accepted), and Social Security card with new name (copies not accepted). If not REAL ID compliant: also bring a primary identity document and two proofs of St. Lucie County residential address. If already REAL ID compliant (gold star), you only need your name change document(s).", "requiredDocuments": ["Current or expired Florida driver license", "Certified name change documentation (marriage certificate, divorce decree, certificate of naturalization showing new name, or court order -- church-issued marriage certificates not accepted)", "Social Security card with new name (copies not accepted)", "Primary identity document (if not already REAL ID compliant -- US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Two proofs of St. Lucie County residential address (if not already REAL ID compliant)"], "onlineEligible": false, "relatedTransactionIds": ["vehicle-title-transfer"], "relatedPrompts": {"vehicle-title-transfer": "Do you also need to update the name on your vehicle title?"}, "notes": "IMPORTANT: You must update your name with the Social Security Administration 24-48 hours BEFORE visiting the Tax Collector office. Church-issued marriage certificates are not accepted. If your current license is not REAL ID compliant, you will need full identity documents in addition to your name change documents. Immigrants must also update USCIS documents to reflect the name change before visiting."}', 20, 'active', FALSE, NULL, NULL, NULL),
('dl-address-change', 'Driver License Address Change', '{"summary": "Update your residential address on your Florida driver license or ID card after moving within Florida.", "keywords": ["address change", "moved", "new address", "update address", "change address"], "commonPhrases": ["I moved to a new address in Florida", "change my address on my license", "update my address", "I need to change my address"], "requiredDocumentSummary": "Current Florida driver license and two proofs of new St. Lucie County residential address (utility bill, bank statement, lease agreement, etc.) dated within the last 60 days, showing you have lived at the address for more than 30 days.", "requiredDocuments": ["Current or expired Florida driver license", "Two proofs of new St. Lucie County residential address dated within the last 60 days showing residency of more than 30 days (utility bill, bank statement, lease agreement, deed, voter registration card, etc.)"], "onlineEligible": true, "onlineUrl": "https://mydmvportal.flhsmv.gov/Home/en/Account/Landing", "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Florida law requires address update within 10 days of moving. Can often be done online at mydmvportal.flhsmv.gov or by mail unless REAL ID upgrade is also needed. Address proof documents must be dated within 60 days and show residency of more than 30 days."}', 10, 'active', TRUE, 'https://mydmvportal.flhsmv.gov/Home/en/Account/Landing', NULL, NULL),
('vehicle-title-transfer', 'Vehicle Title Transfer', '{"summary": "Transfer a vehicle title into your name after purchase, gift, or inheritance. Also covers transferring an out-of-state title to Florida.", "keywords": ["title", "transfer", "vehicle", "car", "bought", "purchased", "gift", "inherited", "out of state title", "new owner"], "commonPhrases": ["I bought a car and need to transfer the title", "transfer my title", "transfer my vehicle title", "I need to title my car in Florida", "put the car in my name", "transfer title from another state", "I was given a car", "private sale", "bought a used car", "inherited a car", "gifted a vehicle"], "requiredDocumentSummary": "Completed Title Application (HSMV 82040), original title (properly assigned/signed by seller), valid government-issued photo ID for each applicant (must be present to sign), proof of current Florida PDL and PIP insurance with company name and policy number, and VIN verification if from out of state. If financed: lienholder documentation. If purchased within 6 months: proof of sales tax paid.", "requiredDocuments": ["Completed Application for Certificate of Title (HSMV 82040)", "Original vehicle title (properly assigned/signed by previous owner)", "Valid government-issued photo ID for each applicant (each person signing must be present)", "Proof of current Florida property damage liability (PDL) and personal injury protection (PIP) insurance, including company name and policy number", "VIN and odometer verification form (HSMV 82042 or Section 7 of HSMV 82040 -- required for out-of-state vehicles, completed by FL DMV compliance examiner, FL licensed dealer, FL notary, law enforcement officer, or US Military Police)", "Current out-of-state registration (if vehicle is from out of state)", "Lienholder documentation: letter on lienholder letterhead with VIN, make, and year, OR copy of out-of-state title showing lien (if lien exists). For leases: copy of lease agreement showing VIN, make, and year.", "Proof of sales tax paid (if owned less than 6 months -- full 6% Florida Use Tax plus applicable local option tax due on vehicles imported from foreign countries)", "Copy of military orders (if applicable)"], "onlineEligible": false, "relatedTransactionIds": ["vehicle-registration", "dl-transfer"], "relatedPrompts": {"vehicle-registration": "Do you also need to register this vehicle in Florida?", "dl-transfer": "If you''re new to Florida, do you also need to get a Florida driver license?"}, "notes": "If vehicle is from out of state, VIN verification and out-of-state registration are required. Each applicant must be present with personal identification to sign the application. Florida Use Tax (6%) plus applicable local option tax applies if purchased within the last 6 months; full 6% plus local option tax due on all vehicles imported from foreign countries. If the vehicle has a lien or is leased, appropriate documentation is required. Copy of military orders required if applicable."}', 20, 'active', FALSE, NULL, NULL, NULL),
('vehicle-registration', 'Vehicle Registration (New or Transfer)', '{"summary": "Register a vehicle in Florida for the first time, or transfer an out-of-state registration to Florida.", "keywords": ["registration", "register", "vehicle", "car", "plate", "tag", "new registration", "out of state"], "commonPhrases": ["register my car in Florida", "I need a Florida plate", "get Florida tags", "transfer my registration to Florida", "register my vehicle"], "requiredDocumentSummary": "Florida vehicle title (or pending title application), valid government-issued photo ID, proof of current Florida PDL and PIP insurance with company name and policy number, and previous registration if transferring from out of state.", "requiredDocuments": ["Florida vehicle title or pending title application", "Valid government-issued photo ID", "Proof of current Florida property damage liability (PDL) and personal injury protection (PIP) insurance, including company name and policy number", "Previous out-of-state registration (if transferring)"], "onlineEligible": false, "relatedTransactionIds": ["vehicle-title-transfer"], "relatedPrompts": {"vehicle-title-transfer": "Do you also need to transfer the vehicle title to Florida?"}, "notes": "Initial registration must be completed in person at one of the three office locations. Registration typically accompanies title work. If the customer already has a Florida title, this may be simpler. Various suspensions/violations (parking, toll violations) may place a hold on registration."}', 15, 'active', FALSE, NULL, NULL, NULL),
('registration-renewal', 'Vehicle Registration Renewal', '{"summary": "Renew an existing Florida vehicle registration. Can often be completed online or at an express lane.", "keywords": ["renew", "renewal", "registration", "tag", "plate", "sticker", "expired tag"], "commonPhrases": ["renew my registration", "renew my tag", "my registration is expiring", "I need a new sticker", "renew my plate"], "requiredDocumentSummary": "Previous registration or registration renewal notice, Florida driver''s license, and current proof of Florida Property Damage and Personal Injury Protection insurance issued by a Florida agent or broker.", "requiredDocuments": ["Previous registration or registration renewal notice", "Florida driver''s license", "Current proof of Florida Property Damage and Personal Injury Protection insurance issued by a Florida agent or broker"], "onlineEligible": true, "onlineUrl": "https://renewexpress.com", "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Registration renewals can be done online through MyEasyGov (payment.myeasygov.com), also available via RenewExpress (renewexpress.com/stlucie/renewals) with same-day pickup if paid before 3 PM, by mail, or in person. A penalty fee is charged for late renewal if not renewed before the 11th day of the month following expiration. Various suspensions/violations may place a hold on registration."}', 10, 'active', TRUE, 'https://renewexpress.com', NULL, NULL),
('road-test', 'Driving Road Test', '{"summary": "Schedule and take a driving road test for a Florida Class E driver license. Available for first-time drivers and teens.", "keywords": ["road test", "driving test", "behind the wheel", "Class E", "first license", "teen", "learner permit"], "commonPhrases": ["I need to take my road test", "schedule a driving test", "I want to get my license for the first time", "my child needs a road test", "take the behind the wheel test"], "requiredDocumentSummary": "Valid Florida learner''s permit, REAL ID identity documents, a vehicle with valid registration and current Florida PIP and PDL insurance for the road test. If under 18: completed Certification of Driving Experience of a Minor (HSMV 71143), which must be notarized if parent/guardian is not accompanying the driver.", "requiredDocuments": ["Valid Florida learner''s permit (held for at least 1 year or until age 18)", "REAL ID identity documents (see Driver License & IDs requirements)", "Vehicle with valid registration for the road test", "Proof of current Florida Personal Injury Protection (PIP) and Property Damage Liability (PDL) insurance on the test vehicle", "Completed Certification of Driving Experience of a Minor (HSMV 71143) -- must be notarized if parent/guardian is not present (if under 18)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Road tests are by appointment only and are available at all three office locations. All testing services end at 3:30 PM. Must bring your own vehicle with valid registration and PIP/PDL insurance. Beginning Feb. 6, 2026, all driving tests are administered exclusively in English; language translation services no longer permitted. If under 18: must be at least 16, must have held learner''s permit for at least 1 year or until age 18, must have no traffic convictions, parental consent forms must be notarized if parent is not present."}', 45, 'active', FALSE, NULL, NULL, NULL),
('property-tax', 'Property Tax Payment', '{"summary": "Pay real property taxes for St. Lucie County. Includes annual property taxes, delinquent taxes, and tax certificate redemptions.", "keywords": ["property tax", "taxes", "tax bill", "real estate tax", "tax payment", "delinquent", "tax certificate", "installment plan", "partial payment", "quarterly tax", "DR-534", "tax mailing address", "change my tax address", "real estate address change", "homestead exemption", "property appraiser"], "commonPhrases": ["pay my property taxes", "I need to pay my tax bill", "property tax payment", "pay taxes on my house", "tax certificate", "sign up for the installment plan", "pay my taxes in installments", "split my property tax into 4 payments", "make a partial payment on my property taxes", "update my mailing address for taxes", "change the address on my property tax bill", "apply for homestead exemption", "am I eligible for a senior exemption"], "requiredDocumentSummary": "Tax bill or parcel ID number, and accepted payment method (check, money order, cash, or credit/debit card with processing fee).", "requiredDocuments": ["Tax bill or parcel ID number", "Payment method (check, money order, cash, or credit/debit card)"], "onlineEligible": true, "onlineUrl": "https://stlucie.county-taxes.com/tcb/app/re/accounts", "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Property taxes can be paid online at stlucie.county-taxes.com. Early payment discounts: 4% November, 3% December, 2% January, 1% February. Taxes are due by March 31; unpaid taxes become delinquent April 1. Partial payments available Nov-March (minimum $100 each, up to 3 partial payments, no discounts on partial payments). Installment plan available (apply by April 30). Online payment fees: e-check $0.50, credit card 2.5%. In-person payment at any Tax Collector office."}', 10, 'active', TRUE, NULL, NULL, NULL),
('concealed-weapon', 'Concealed Weapon Permit', '{"summary": "Apply for or renew a Florida Concealed Weapon or Firearm License (CWFL). Fingerprinting and application processing.", "keywords": ["concealed weapon", "concealed carry", "firearm", "gun permit", "CWFL", "concealed license", "weapon permit"], "commonPhrases": ["I need a concealed carry permit", "apply for concealed weapon license", "get my concealed carry", "renew my concealed weapon permit", "fingerprinting for gun permit"], "requiredDocumentSummary": "Valid Florida driver license or ID, proof of firearms training (certificate of completion from an approved course), passport-style photo, and application fee payment.", "requiredDocuments": ["Valid Florida driver license or ID", "Proof of firearms training (certificate of completion from approved course)", "Passport-style photo", "Application fee payment"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "ONLY available at the Walton Road office (1664 SE Walton Road, Port St. Lucie), Tuesday through Thursday, 9:00 a.m. to 4:00 p.m., by appointment only. Requirements are set by the Florida Department of Agriculture and Consumer Services (FDACS) -- see fdacs.gov/Consumer-Resources/Concealed-Weapon-License for current requirements. Processing takes several weeks through FDACS."}', 30, 'active', FALSE, NULL, NULL, NULL),
('hunting-fishing', 'Hunting & Fishing License', '{"summary": "Purchase or renew Florida hunting and fishing licenses and permits.", "keywords": ["hunting", "fishing", "license", "permit", "outdoor", "sportsman"], "commonPhrases": ["I need a fishing license", "buy a hunting license", "get a fishing permit", "renew my hunting license"], "requiredDocumentSummary": "Valid Florida driver license or ID. If claiming residency discount: proof of Florida residency.", "requiredDocuments": ["Valid Florida driver license or ID", "Proof of Florida residency (if claiming residency discount)"], "onlineEligible": true, "onlineUrl": "https://myfwc.com/license/recreational/how-to-order/", "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Can also be purchased online through myfwc.com. In-person available at Tax Collector offices. Florida residents aged 65 or older do not need to purchase a license -- a Florida driver''s license or ID card suffices as proof of age and residency. Military members may qualify for the Military Gold Sportsman''s License (see myfwc.com/license/recreational/military-gold/)."}', 10, 'active', TRUE, NULL, NULL, NULL),
('vessel-registration', 'Vessel / Boat Registration', '{"summary": "Register a vessel or boat in Florida, transfer registration from another state, or renew an existing registration.", "keywords": ["boat", "vessel", "watercraft", "marine", "boat registration", "vessel registration"], "commonPhrases": ["register my boat", "I bought a boat and need to register it", "transfer my boat registration to Florida", "renew my vessel registration"], "requiredDocumentSummary": "Vessel title or manufacturer''s statement of origin, previous registration if transferring, valid Florida driver license or ID, and proof of payment for sales tax if applicable.", "requiredDocuments": ["Application for Certificate of Vessel Title (HSMV 82040 VS) for new titles", "Vessel title or manufacturer''s statement of origin", "Previous registration (if transferring)", "Valid government-issued photo ID", "Proof of sales tax payment (if applicable)"], "onlineEligible": true, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Initial registration must be completed in person at one of the three office locations. Renewals can be completed online at renewexpress.com/stlucie/renewals or in person. All motorized vessels operated on Florida waters must be registered. Non-residents must register if vessel is used in Florida waters more than 90 days. Registration fees vary by vessel length ($15.50 for canoes under 12'' up to $291.88 for 110''+).", "onlineUrl": "https://renewexpress.com/stlucie/renewals"}', 20, 'active', TRUE, NULL, NULL, NULL),
('handicap-placard', 'Disabled Parking Permit (Handicap Placard)', '{"summary": "Apply for, renew, or replace a disabled parking permit (handicap placard). Long-term permits are free and valid for 4 years. Temporary permits cost $15 and are valid up to 6 months.", "keywords": ["handicap", "placard", "disabled", "parking", "disability", "wheelchair", "accessible", "permit"], "commonPhrases": ["I need a handicap placard", "get a disabled parking permit", "handicap parking tag", "renew my handicap placard", "I need a replacement placard", "disabled parking placard", "apply for a handicap permit"], "requiredDocumentSummary": "Completed Disabled Parking Permit Application (HSMV 83039) signed by a qualifying professional (Florida or out-of-state physician, osteopathic physician, podiatrist, chiropractor, optometrist, APRN licensed under Chapter 464, Florida Division of Blind Services, Florida Department of Veterans Affairs, or Adjudication Office of the US Department of Veterans Affairs). The application is valid for one year from the signature date. You also need a current Florida driver license or ID card. Temporary permits cost $15; long-term permits are free.", "requiredDocuments": ["Completed Disabled Parking Permit Application (HSMV 83039) signed by qualifying medical professional", "Valid Florida driver license or ID"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Long-term permits are free, valid 4 years, and expire on the applicant''s birthday. Temporary permits cost $15 and are valid up to 6 months as determined by a physician. The application form can be downloaded from tcslc.com or obtained at the office. Most doctors provide and fill out this form; applicants may fill in their own info at the top. Out-of-state physicians must be licensed under equivalent statutes and submit documentation of their licensure. The same application form is used for initial issuance, renewals, and replacements. Knowingly providing false information is a misdemeanor of the first degree (up to 1 year in jail and/or $1,000 fine)."}', 10, 'active', FALSE, NULL, NULL, NULL),
('dl-replacement', 'Driver License / ID Card Replacement', '{"summary": "Replace a lost, stolen, or damaged Florida driver license or ID card. A duplicate credential is issued with the same expiration date.", "keywords": ["replacement", "lost", "stolen", "damaged", "duplicate", "license", "ID card", "replace"], "commonPhrases": ["I lost my license", "my license was stolen", "I need a replacement license", "my ID card is damaged", "replace my driver license", "get a duplicate license"], "requiredDocumentSummary": "If your current credential is REAL ID compliant (gold star), fewer documents may be needed. If not REAL ID compliant: one primary identity document, your Social Security card (copies not accepted), and two proofs of St. Lucie County residential address. Replacement fee applies.", "requiredDocuments": ["Primary identity document if not REAL ID compliant (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card if not REAL ID compliant (copies not accepted)", "Two proofs of St. Lucie County residential address if not REAL ID compliant", "Replacement fee payment"], "onlineEligible": false, "relatedTransactionIds": ["real-id-upgrade"], "relatedPrompts": {"real-id-upgrade": "Would you like to upgrade to a REAL ID-compliant license while you''re getting your replacement?"}, "notes": "If the license was stolen, bringing a police report number may waive certain fees. This is a good opportunity to upgrade to REAL ID if the customer hasn''t already."}', 15, 'active', FALSE, NULL, NULL, NULL),
('id-card', 'Florida Identification Card', '{"summary": "Apply for or renew a Florida state identification card. For residents who do not drive but need official state-issued photo identification.", "keywords": ["ID card", "identification card", "state ID", "photo ID", "non-driver", "ID"], "commonPhrases": ["I need a state ID", "get a Florida ID card", "I don''t drive but need an ID", "apply for an identification card", "I need a photo ID"], "requiredDocumentSummary": "One primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad), your Social Security card (copies not accepted), and two proofs of St. Lucie County residential address. Same REAL ID document requirements as a driver license.", "requiredDocuments": ["Primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card (copies not accepted)", "Two proofs of St. Lucie County residential address (utility bill, bank statement, lease agreement, deed, voter registration card, etc.)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Same document requirements as a driver license. REAL ID-compliant ID cards are available. Useful for residents who don''t drive, including seniors, teens, and those with suspended licenses."}', 20, 'active', FALSE, NULL, NULL, NULL),
('real-id-upgrade', 'REAL ID Upgrade', '{"summary": "Upgrade your existing Florida driver license or ID card to be REAL ID-compliant (gold star). Required for domestic air travel and entering federal buildings. Must be done in person.", "keywords": ["REAL ID", "gold star", "upgrade", "compliant", "TSA", "federal", "star on license", "flying"], "commonPhrases": ["I need a REAL ID", "upgrade to REAL ID", "get the gold star on my license", "I need my license for flying", "my license doesn''t have the star", "REAL ID compliant"], "requiredDocumentSummary": "One primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad), your Social Security card (copies not accepted), and two proofs of St. Lucie County residential address. If your name has changed, bring certified name change documents showing the complete chain from birth certificate name to current name. Church-issued marriage certificates not accepted.", "requiredDocuments": ["Primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card (copies not accepted)", "Two proofs of St. Lucie County residential address (utility bill, bank statement, lease agreement, deed, voter registration card, etc.)", "Certified name change documents if name has changed since primary ID (marriage certificate, divorce decree, court order -- church-issued marriage certificates not accepted)"], "onlineEligible": false, "relatedTransactionIds": ["dl-address-change", "dl-name-change"], "relatedPrompts": {"dl-address-change": "Has your address changed? We can update that at the same time as your REAL ID upgrade.", "dl-name-change": "Has your legal name changed since your last license? We can update that too."}, "notes": "Cannot be done online -- requires in-person visit. The gold star indicates REAL ID compliance. A REAL ID checklist PDF is available on tcslc.com. Name change documentation chain must be complete (e.g., birth certificate name -> marriage certificate -> current name). Church-issued marriage certificates are not accepted. Note: REAL ID requirements above pertain to Class E driver licenses only; CDL/CLP have separate requirements."}', 20, 'active', FALSE, NULL, NULL, NULL),
('cdl', 'Commercial Driver License (CDL)', '{"summary": "Apply for, renew, or upgrade a Commercial Driver License. Required for operating vehicles over 26,001 lbs GVWR, hazardous materials transport, or vehicles carrying 16+ passengers.", "keywords": ["CDL", "commercial", "truck", "semi", "hazmat", "bus", "commercial driver", "Class A", "Class B"], "commonPhrases": ["I need a CDL", "get a commercial driver license", "CDL renewal", "I want to drive a truck commercially", "commercial license", "hazmat endorsement"], "requiredDocumentSummary": "Valid Florida driver license, proof of US citizenship or lawful permanent residency, Social Security card, medical examiner''s certificate (DOT physical), CDL application, and any applicable endorsement test results. REAL ID documents required if not already compliant.", "requiredDocuments": ["Valid Florida driver license or ID", "Proof of US citizenship or lawful permanent residency", "Social Security card (copies not accepted)", "Medical examiner''s certificate (DOT physical)", "CDL application", "Endorsement test results (if applicable)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "CDL applicants must pass written knowledge tests and a skills test. Hazmat endorsement requires TSA background check. Medical examiner''s certificate must be current. CDL residential address requirements differ from Class E -- check tcslc.com/301 for details. Beginning Feb. 6, 2026, all exams are in English only. Not all offices may handle CDL -- verify with the office."}', 30, 'active', FALSE, NULL, NULL, NULL),
('learner-permit', 'Learner''s Permit', '{"summary": "Apply for a Florida learner''s permit. For first-time drivers (teens under 18 and adults 18+). Teens must complete required courses before applying.", "keywords": ["learner", "permit", "learners permit", "first time driver", "teen", "beginner", "student driver", "learning to drive"], "commonPhrases": ["I need a learner''s permit", "my kid needs a learner''s permit", "get a permit to learn to drive", "first time driver permit", "teen learner permit", "I want to start learning to drive"], "requiredDocumentSummary": "Under 18: Primary identity document (birth certificate or passport), Social Security card (copies not accepted), two proofs of St. Lucie County residential address from parent/guardian, proof of DETS course completion, and parental consent form (notarized if parent not present). Must be at least 15 to test. Age 18+: Primary identity document, Social Security card (copies not accepted), two proofs of St. Lucie County residential address, and proof of TLSAE course completion.", "requiredDocuments": ["Primary identity document (US passport, birth certificate, certificate of naturalization, certificate of citizenship, or consular report of birth abroad)", "Social Security card (copies not accepted)", "Two proofs of St. Lucie County residential address (if minor: must be from parent/step-parent/legal guardian or person minor resides with, plus proof of family relationship OR Certification of Address form with person present)", "Proof of required course completion (DETS 6-hour course for under 18 starting Aug 2025, TLSAE 4-hour course for 18+; students who completed TLSAE before Aug 2025 are exempt from DETS)", "Parental consent form (HSMV 71142), must be notarized if parent/legal guardian is not present (if under 18)"], "onlineEligible": false, "relatedTransactionIds": ["written-test"], "relatedPrompts": {"written-test": "You''ll also need to pass the written knowledge exam. Would you like to schedule that at the same time?"}, "notes": "Under 18: Must be at least 15 to test. Must hold permit at least 1 year or until age 18. First 3 months: daylight driving only. After 3 months: until 10 PM. Must be accompanied by licensed driver 21+. 50 supervised driving hours required (10 at night). Students who completed TLSAE before August 2025 are exempt from the new DETS requirement. Age 18+: No holding period but must be accompanied by licensed driver 21+. Can test online if under 18 (may be randomly selected for mandatory in-person re-test); must test in person if 18+. Beginning Feb. 6, 2026, all exams in English only. Parental forms must be notarized if parent/guardian is not present."}', 30, 'active', FALSE, NULL, NULL, NULL),
('written-test', 'Written Knowledge Exam (Road Rules & Signs)', '{"summary": "Take the written knowledge exam (Road Rules and Signs test) required for a Florida driver license. 50 multiple-choice questions with one hour to complete.", "keywords": ["written test", "knowledge exam", "road signs", "road rules", "permit test", "DL exam", "driver test"], "commonPhrases": ["I need to take the written test", "schedule a knowledge exam", "take the permit test", "road signs and rules test", "driver license exam"], "requiredDocumentSummary": "Valid learner''s permit or identity documents if applying for the permit at the same time. Proof of required course completion (DETS for under 18, TLSAE for 18+).", "requiredDocuments": ["Valid learner''s permit or identity documents", "Proof of required course completion (DETS for under 18, TLSAE for 18+)"], "onlineEligible": false, "relatedTransactionIds": ["learner-permit"], "relatedPrompts": {"learner-permit": "Do you also need to apply for your learner''s permit?"}, "notes": "Written testing available until 3:30 PM. Applicants under 18 may take the test online through an authorized third-party (may be randomly selected for mandatory in-person re-test); those 18+ must test in person at the Tax Collector office. The exam is 50 multiple-choice questions with one hour to complete. Must be at least 15 years old. Beginning Feb. 6, 2026, all knowledge exams are in English only; language translation services no longer permitted. Study materials available at flhsmv.gov handbooks and manuals."}', 45, 'active', FALSE, NULL, NULL, NULL),
('duplicate-title', 'Duplicate Vehicle Title', '{"summary": "Apply for a duplicate vehicle title when the original has been lost, stolen, or damaged. Only the registered owner or lienholder on record may apply.", "keywords": ["duplicate title", "lost title", "replacement title", "title copy", "stolen title", "damaged title"], "commonPhrases": ["I lost my vehicle title", "I need a duplicate title", "replace my car title", "my title was damaged", "get a copy of my title"], "requiredDocumentSummary": "Completed application for duplicate title, valid photo ID. If there is an active lien, only the lienholder can request the duplicate. If the lien has been satisfied, bring a lien satisfaction form or paper release. For out-of-state titles, you must apply through that state''s DMV.", "requiredDocuments": ["Completed Application for Duplicate or Lost in Transit (HSMV 82101)", "Valid government-issued photo ID", "Lien satisfaction form or paper release (if lien has been satisfied)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Only the registered owner or lienholder on record can apply. Out-of-state titled vehicles must get duplicate titles from the issuing state. If a lien exists, only the lienholder can request it."}', 15, 'active', FALSE, NULL, NULL, NULL),
('new-vehicle-title', 'New Vehicle Title Application (Dealer Purchase)', '{"summary": "Title application for a newly purchased vehicle from a dealership. Florida dealers are required by law to process your title, but you may need to visit if there are issues or if you purchased from an out-of-state dealer.", "keywords": ["new title", "dealer", "purchased", "bought new car", "dealership", "new vehicle"], "commonPhrases": ["I bought a new car from a dealer", "I need to title my new vehicle", "dealer title application", "title for a car I just bought", "out of state dealer title", "new dealer purchase", "got a new car at the lot", "MCO", "manufacturer certificate of origin", "first time titling"], "requiredDocumentSummary": "Completed Application for Motor Vehicle Title (HSMV 82040), manufacturer''s certificate of origin or dealer-assigned title, bill of sale or dealer invoice, federal odometer statement, valid government-issued photo ID (each applicant must sign in person), proof of FL PDL/PIP insurance if getting plates, and lienholder information if financed.", "requiredDocuments": ["Completed Application for Motor Vehicle Title (HSMV 82040)", "Original manufacturer''s certificate of origin or dealer-assigned title", "Bill of sale or dealer invoice listing purchase price, sales tax paid, and any trade-in allowance", "Federal odometer statement", "Valid government-issued photo ID (each applicant must be present to sign)", "Proof of current Florida PDL and PIP insurance, including company name and policy number (when purchasing a license plate or extending registration period)", "Any applicable lienholder information (if financed)", "Current registration or plate number (if transferring a plate)"], "onlineEligible": false, "relatedTransactionIds": ["vehicle-registration"], "relatedPrompts": {"vehicle-registration": "Do you also need to register the vehicle and get Florida plates?"}, "notes": "Florida dealers are required by law to handle title processing. This service is typically needed when purchasing from an out-of-state dealer, a private sale of a new vehicle, or resolving title issues from a dealer transaction."}', 20, 'active', FALSE, NULL, NULL, NULL),
('tag-replacement', 'Lost or Stolen Tag / Decal Replacement', '{"summary": "Replace a lost, stolen, or damaged license plate (tag) or registration decal. If stolen, report to law enforcement first.", "keywords": ["lost tag", "stolen tag", "lost plate", "stolen plate", "decal", "replacement tag", "missing plate", "license plate"], "commonPhrases": ["my license plate was stolen", "I lost my tag", "I need a replacement plate", "my decal is missing", "replace my stolen plate", "lost registration sticker"], "requiredDocumentSummary": "You must first contact local law enforcement to report the loss or theft. Then bring the completed Application for Replacement, valid photo ID, and the case number from law enforcement. Lost tag: $36.90, lost decal: $34.10. Stolen tag and decal: no cost with law enforcement case number.", "requiredDocuments": ["Completed Application for Replacement License Plate, Validation Decal, or Parking Permit", "Valid government-issued photo ID", "Police report/case number from local law enforcement (must report loss or theft BEFORE applying for replacement)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "You must report the loss or theft to local law enforcement BEFORE applying for a replacement. Stolen items: no cost to replace if you provide the case number from law enforcement. Lost items: $36.90 for tag, $34.10 for decal. The replacement application form is available on tcslc.com."}', 10, 'active', FALSE, NULL, NULL, NULL),
('plate-surrender', 'License Plate Surrender', '{"summary": "Return/surrender your Florida license plates and registration. Required when selling a vehicle, moving out of state, canceling insurance, or after a vehicle is repossessed.", "keywords": ["surrender", "return plate", "turn in plate", "cancel registration", "moving out of state", "sold car"], "commonPhrases": ["I need to turn in my plates", "surrender my license plate", "return my tag", "I sold my car and need to return the plate", "I''m moving out of Florida", "cancel my registration"], "requiredDocumentSummary": "License plate(s) to surrender, valid photo ID. If surrendering by mail: signed written statement and copy of photo ID. If someone other than the owner is surrendering: their ID plus a completed License Plate Surrender Affidavit.", "requiredDocuments": ["License plate(s) and decal(s) to surrender", "Valid government-issued photo ID", "License Plate Surrender Affidavit (if someone other than the owner/registrant is surrendering)"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Can be done in person at any office (no appointment needed) or by mail (P.O. Box 308, Fort Pierce, FL 34954 -- include signed written statement specifying reason and copy of photo ID). If someone other than the owner is surrendering, they need their photo ID and a completed License Plate Surrender Affidavit. If you have active Financial Responsibility suspensions, you must provide proof of insurance or surrender plates before the suspension date. Reinstatement fees: $156.25 first offense, $256.25 second within 3 years, $506.25+ subsequent. Free DL suspension check at services.flhsmv.gov/DLCheck/"}', 10, 'active', FALSE, NULL, NULL, NULL),
('specialty-plate', 'Specialty or Personalized License Plate', '{"summary": "Order a specialty license plate with a unique design supporting a specific organization, or a personalized plate with custom characters.", "keywords": ["specialty plate", "personalized plate", "custom plate", "vanity plate", "special plate", "organization plate"], "commonPhrases": ["I want a specialty license plate", "get a personalized plate", "custom license plate", "vanity plate", "I want a plate that supports", "order a special plate"], "requiredDocumentSummary": "For personalized plates: completed HSMV Form 83043, $15 annual fee, must be ordered in person. For specialty plates: current vehicle registration, additional annual fee varies by plate type. Check plate availability online before visiting.", "requiredDocuments": ["Current vehicle registration", "Completed HSMV Form 83043 (for personalized plates)", "Application fee payment"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Personalized plates cost $15/year and must be ordered in person using HSMV Form 83043. Check availability at services.flhsmv.gov/MVCheckPersonalPlate/ before visiting. Specialty plates support various organizations and have varying additional fees. See flhsmv.gov for the full list of available specialty plates. Presale vouchers for newly approved specialty plates available at govhub.com/stlucie/vouchers."}', 15, 'active', FALSE, NULL, NULL, NULL),
('mobile-home-title', 'Mobile Home Title & Registration', '{"summary": "Title and register a mobile home in Florida. Includes new titles, transfers, and annual registration decal renewals. Decals expire December 31 each year.", "keywords": ["mobile home", "manufactured home", "trailer home", "mobile home title", "mobile home registration", "decal", "double wide"], "commonPhrases": ["I need to title my mobile home", "register a mobile home", "mobile home decal renewal", "transfer mobile home title", "manufactured home registration"], "requiredDocumentSummary": "For new title: application for title, manufacturer''s certificate of origin or previous title, bill of sale, lien information if financed. For out-of-state: original title, current registration, lien info. For renewal: current registration or renewal notice. All applicants must sign in person. Florida Use Tax may be due if purchased less than 6 months ago.", "requiredDocuments": ["Application for Certificate of Mobile Home Title (HSMV 82040 MH)", "Manufacturer''s certificate of origin or previous title", "Bill of sale or invoice listing purchase price, sales tax paid, and any trade-in allowance", "Lienholder information including account number, name, and mailing address (if financed)", "Current registration, decal number, or renewal notice (for renewals or decal transfers)", "Out-of-state title certificate (if from out of state)"], "onlineEligible": false, "relatedTransactionIds": ["mobile-home-retire"], "relatedPrompts": {"mobile-home-retire": "If you own both the mobile home and the land it sits on, you may want to retire the title to a deed. Would you like information on that?"}, "notes": "Mobile home must be registered with a current decal at all times, even when unoccupied -- failure could result in tangible personal property tax assessment by the Property Appraiser. One decal per unit (double/triple-wide: one per section). Registration fees vary by length ($31.85 through 35'' up to $91.85 over 65''). Decals expire December 31. Florida Use Tax (6%) may be due if purchased less than 6 months ago; full 6% plus local option tax for foreign imports. RP declaration available for $5.10 permanent decal if you own both home and land -- contact Property Appraiser''s office first. Florida dealers are required by law to process title applications."}', 20, 'active', FALSE, NULL, NULL, NULL),
('mobile-home-retire', 'Retire Mobile Home Title (Convert to Deed)', '{"summary": "Retire a mobile home''s DMV title and convert it to a warranty deed. This makes the mobile home part of the real property (land), so future transfers are done via deed rather than motor vehicle title application.", "keywords": ["retire title", "mobile home deed", "convert to deed", "real property", "permanent", "retire mobile home"], "commonPhrases": ["retire my mobile home title", "convert mobile home to real property", "make my mobile home part of the land", "mobile home to deed", "retire the title on my manufactured home"], "requiredDocumentSummary": "Two-step process: First, file with the St. Lucie County Clerk of Circuit Court (call 772-462-6900 for required fees). Then bring to the Tax Collector: completed Application for Retirement (HSMV 82109, one per unit), copy of the recorded documents from the Clerk, and proof all tangible tax bills are paid in full. If names are joined by ''and,'' each owner must sign. No fees at the Tax Collector''s office.", "requiredDocuments": ["Completed Application for Retirement of a Mobile Home Certificate of Title (HSMV 82109) -- one application per unit for double/triple wide", "Copy of documents recorded with the Clerk of Circuit Court (must be filed and recorded there first)", "All tangible tax bills paid in full"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Two-step process: (1) File with the Clerk of Circuit Court first (separate fees apply -- visit stlucieclerk.gov or call 772-462-6900), (2) Then file with the Tax Collector''s office (no fees). One application required per unit for double/triple wide. If ownership names are joined by ''and,'' each owner must sign. All tangible tax bills must be paid in full before processing. Once retired, the mobile home is treated as real property and future transfers use a deed, not a motor vehicle title application."}', 20, 'active', FALSE, NULL, NULL, NULL),
('dl-sanctions-lift', 'Driver License Reinstatement (After Suspension or Revocation)', '{"summary": "Reinstate a suspended, revoked, or cancelled Florida driver license. Covers DUI, traffic-court suspensions, child-support delinquency, failure-to-comply, course-completion issues, and related scenarios. Some paths include a hardship license application.", "keywords": ["reinstate", "reinstatement", "suspended", "suspension", "revoked", "revocation", "DUI", "DWI", "hardship license", "sanctions", "get my license back", "SR-22", "child support", "failure to appear", "failure to comply"], "commonPhrases": ["my license is suspended", "I need to reinstate my license", "how do I get my license back", "I had a DUI", "hardship license", "my license was revoked", "I paid my ticket how do I fix my license", "SR22 insurance"], "requiredDocumentSummary": "Valid photo ID, plus path-specific documents the clerk needs to confirm your underlying issue is cleared. Typical items include a court clearance letter, completion certificates for Advanced Driver Improvement (ADI) or DUI Program, SR-22 insurance filing, IID installation proof for DUI hardship, and the reinstatement fee. Exact requirements depend on the reason for the suspension -- we''ll walk through the right set for your situation.", "requiredDocuments": ["Valid photo ID", "Court clearance letter or FLHSMV notification (if underlying issue was court-related)", "Advanced Driver Improvement (ADI) course completion certificate (if required for your sanction type)", "Licensed DUI Program completion certificate (if DUI-related)", "SR-22 proof of insurance (if required for your sanction type)", "IID (Ignition Interlock Device) installation verification (if DUI hardship path)", "HSMV 78306 Application for Driver License Hardship Hearing (if pursuing hardship license)", "Reinstatement fee payment"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Several suspension types are indefinite AND not eligible for hardship license: child-support delinquency (resolve through FL Dept of Revenue 850-488-5437), failure-to-comply / failure-to-appear suspensions, failure to complete court-ordered driver improvement school. For these, the customer must satisfy the issuing agency first; clearance flows to FLHSMV electronically before the reinstatement fee can be paid here. DUI hardship requires FLHSMV Administrative Reviews (separate office, not the Tax Collector counter) for the hearing. SR-22 must be filed by the customer''s insurance carrier directly with FLHSMV. See tree dl-sanctions-lift.json for the branch matrix.", "sourcePages": ["https://www.flhsmv.gov/driver-licenses-id-cards/driver-license-suspensions-revocations/", "https://www.tcslc.com/291/Driving-Improvement-Courses"]}', 30, 'active', FALSE, NULL, NULL, NULL),
('business-tax-receipt', 'Local Business Tax Receipt (BTR)', '{"summary": "Apply for or renew a St. Lucie County Local Business Tax Receipt. Required for any business or profession located in St. Lucie County per County Ordinance 07-016. Not required for W-2 employees of another business; 1099 contractors do need their own.", "keywords": ["business tax", "BTR", "business tax receipt", "business license", "local business tax", "start a business", "occupational license", "new business", "renew business tax"], "commonPhrases": ["I''m starting a business", "I need a business license", "business tax receipt", "BTR", "renew my business license", "occupational license", "I''m a 1099 contractor"], "requiredDocumentSummary": "Valid photo ID, a SunBiz fictitious-name registration (if operating under any name other than your legal first+last name), state-agency license (for regulated professions), municipal zoning approval (for businesses in unincorporated areas), and a Fire Inspection if required by your business type. Disabled veterans and un-remarried spouses of deceased disabled veterans qualify for a no-charge BTR with proof of exemption.", "requiredDocuments": ["Valid photo ID", "SunBiz Fictitious Name registration (if operating under a name other than legal first + last)", "Florida state professional license (for regulated professions -- e.g., cosmetology, contractor, real estate)", "St. Lucie County Zoning approval (for businesses in unincorporated areas -- visit stluciecountyfl-energovpub.tylerhost.net or call 772-462-2822)", "Fire Inspection certificate (if required for the business type)", "Disabled Veteran exemption documentation (if claiming exemption)", "BTR application fee payment"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "BTR is issued at no charge for (a) disabled sole proprietors who qualify for Disabled Person exemption AND provide proof of honorable discharge, (b) un-remarried spouse of a deceased disabled veteran. Regulated professions (e.g., cosmetology, real estate, contractors) must present their state license BEFORE the BTR will be issued. Businesses in unincorporated St. Lucie County must complete county zoning review first. W-2 employees of another business do NOT need a BTR; 1099 contractors do. Annual renewal required. See tree business-tax-receipt.json for the branch matrix.", "sourcePages": ["https://www.tcslc.com/227/Local-Business-Tax"]}', 20, 'active', FALSE, NULL, NULL, NULL),
('tourist-development-tax', 'Tourist Development Tax (TDT) Registration', '{"summary": "Register a short-term rental property (rentals of 6 months or less) for the St. Lucie County Tourist Development Tax -- a 5% charge on rental revenue, in addition to state sales tax. Property owners are responsible for TDT on rentals through any platform (Airbnb, VRBO, direct). Online services do NOT pay this on your behalf.", "keywords": ["tourist tax", "tourist development tax", "TDT", "bed tax", "resort tax", "short-term rental", "Airbnb tax", "VRBO tax", "rental tax", "vacation rental", "TouristExpress"], "commonPhrases": ["I rent out my property on Airbnb", "I have a short-term rental", "register for tourist tax", "vacation rental tax", "TDT", "bed tax", "VRBO tax account"], "requiredDocumentSummary": "Valid photo ID, property parcel information (folio or address), and a Florida Department of Revenue (FDOR) sales-tax identification number -- you MUST obtain the FDOR number before registering for TDT. If you use a property manager to handle rentals, bring the owner/agent agreement. Registration itself happens through the TouristExpress online portal or at the office.", "requiredDocuments": ["Valid photo ID", "Property parcel information (folio number, address, or deed)", "FDOR sales-tax identification number (MUST be obtained first from Florida Department of Revenue -- 772-429-2900 or floridarevenue.com)", "Owner-agent agreement (if a property manager will remit tax on your behalf)"], "onlineEligible": true, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "The FDOR sales-tax ID is a hard prerequisite -- without it, we cannot register the TDT account. Customers renting through Airbnb, VRBO, or similar platforms still owe the tax themselves; platforms do not remit it. A 5% rate applies (in addition to state sales tax, total 12% in St. Lucie County). Property managers can be designated as the remitting agent. An online TouristExpress application is available; the online path is preferred. Disabled-veteran and active-military exemptions may apply in narrow cases (see tree). See tree tourist-development-tax.json for the branch matrix.", "sourcePages": ["https://www.tcslc.com/233/Tourist-Development"]}', 15, 'active', TRUE, NULL, NULL, NULL),
('tangible-personal-property-tax', 'Tangible Personal Property Tax', '{"summary": "Pay a Tangible Personal Property (TPP) tax bill from the St. Lucie County Tax Collector. TPP applies to business equipment, fixtures, furnishings in rental units, machinery, leased equipment, and mobile home attachments on rented land. Anyone with assets as of January 1 must FILE the TPP return with the Property Appraiser (not the Tax Collector) by April 1 each year to claim the $25,000 Amendment 1 exemption.", "keywords": ["tangible personal property", "TPP", "business equipment tax", "equipment tax", "furnishings tax", "machinery tax", "business personal property", "leased equipment tax", "rental furnishings tax", "centrally assessed"], "commonPhrases": ["I have a tangible tax bill", "pay my TPP tax", "business equipment tax", "I got a tangible personal property bill", "what is tangible personal property tax", "file my TPP return"], "requiredDocumentSummary": "To PAY an existing TPP bill: the bill (or account number) and payment. To FILE the return (to claim the $25,000 exemption): file directly with the St. Lucie County Property Appraiser at paslc.gov — the Tax Collector does not accept TPP returns. Delinquent TPP taxes must be paid with guaranteed funds (cashier''s check, cash, debit/credit); personal checks are not accepted on delinquencies.", "requiredDocuments": ["TPP tax bill or TPP account number", "Payment (personal check accepted for current-year bills; guaranteed funds required for delinquent)"], "onlineEligible": true, "relatedTransactionIds": ["property-tax"], "relatedPrompts": {"property-tax": "Would you also like to pay your real-property tax bill in the same visit?"}, "notes": "TPP payment happens at the Tax Collector; TPP FILING happens at the Property Appraiser (paslc.gov). If the customer is asking about filing, redirect. If they''re asking how to pay, proceed. The $25,000 Amendment 1 exemption requires filing by April 1 each year. Late filing loses the exemption. Same delinquent-funds rule as real property taxes: personal checks NOT accepted on past-due amounts. Railroads and utilities appear under ''centrally assessed'' — billed the same way. See Florida Statute 193.052.", "sourcePages": ["https://www.tcslc.com/214/Tangible-Centrally-Assessed-Tax"]}', 10, 'active', TRUE, NULL, NULL, NULL),
('dealer-title-dropoff', 'Motor Vehicle Dealer Title Paperwork Drop-Off', '{"summary": "Licensed Florida motor-vehicle dealers submitting customer title and registration paperwork for vehicles they''ve sold. This is a B2B counter service, not a consumer transaction -- the dealer drops off a batch of title applications on behalf of purchasers.", "keywords": ["dealer", "motor vehicle dealer", "title drop-off", "dealer paperwork", "dealer dropoff", "dealer title submission", "dealer agent"], "commonPhrases": ["I''m a dealer dropping off titles", "dealer paperwork", "batch title submission", "my dealership needs to submit titles"], "requiredDocumentSummary": "Valid dealer representative photo ID, active Florida motor-vehicle dealer license (FLHSMV-issued), SunBiz registration for the dealership, completed customer title applications (HSMV 82040 or equivalent) for each vehicle, supporting transfer documents, and odometer disclosure per-vehicle. If any dealer license is expired, dropoff is blocked until renewed with FLHSMV.", "requiredDocuments": ["Valid photo ID for dealer representative", "Active Florida motor-vehicle dealer license (not expired)", "SunBiz corporate registration", "Completed HSMV 82040 (or equivalent) title application per vehicle", "Odometer disclosure statement per vehicle", "Supporting documents (bill of sale, prior title, lienholder info) per vehicle"], "onlineEligible": false, "relatedTransactionIds": [], "relatedPrompts": {}, "notes": "Not a consumer transaction -- this is the B2B counter service for licensed motor-vehicle dealers. If the dealer''s FLHSMV license is expired, dropoff is BLOCKED; they must renew with FLHSMV Motor Vehicle Field Operations before returning (see Bureau of Field Operations Regional Offices directory). Dealers can use the /330/Dealer-Application online form to apply for dealer status. See tree dealer-title-dropoff.json for the branch matrix.", "sourcePages": ["https://www.tcslc.com/216/Dealers-Corner", "https://www.tcslc.com/330/Dealer-Application"]}', 25, 'active', FALSE, NULL, NULL, NULL),
('trailer-registration', 'Trailer Registration', '{"summary": "Register a trailer in Florida — homemade or manufactured, any size. Sub-2,000 lb trailers are registration-only; 2,000-lb-and-up trailers must also be titled.", "category": "Vehicles & Plates", "keywords": ["trailer", "register trailer", "trailer registration", "homemade trailer", "diy trailer", "utility trailer", "motorcycle trailer", "boat trailer", "cargo trailer", "car hauler"], "commonPhrases": ["register a trailer", "register my trailer", "register a homemade trailer", "register a DIY trailer", "register a motorcycle trailer", "register a utility trailer", "register a cargo trailer", "register a boat trailer", "I built a trailer", "homemade trailer registration", "shop-built trailer", "I made a trailer", "trailer I welded together"], "relatedTransactionIds": ["vehicle-title-transfer", "vessel-registration"], "relatedPrompts": ["Boat trailers fall under trailer registration even when paired with vessel registration."], "onlineEligible": false, "notes": "Sub-2,000-lb trailers are statutorily prohibited from being titled in Florida; they are registration-only. The 2,000-lb cutoff is decided by a public-scale weight slip the customer brings to the visit.", "requiredDocumentSummary": "Photo ID + certified weight slip + proof of acquisition (parts receipts for homemade, bill of sale or title for purchased)."}', 20, 'active', FALSE, NULL, NULL, NULL);


